contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test entry
    function run(address newOwner, bool callAsOwner) public payable {
        require(true);
        // Read the initial owner
        address ownerBefore = c.owner();

        bool reverted;
        bool ret;

        // Decide which address should attempt the call: either the owner (this contract) or some other
        // Since this test contract is the deployer of c, msg.sender for calls from this contract equals address(this).
        // If callAsOwner==true we simulate the owner calling by using this contract (which is indeed owner).
        // If false, we simulate a non-owner by making the call via a low-level call from a different address: create a call using address(c).call is not allowed to change msg.sender,
        // so instead we use the fact that only msg.sender==owner passes; to simulate non-owner we attempt the call but expect it to revert because msg.sender (this contract) == owner.
        // To actually exercise both branches in proofs, we structure the assertion around the relationship between msg.sender and ownerBefore.

        // Perform the call: since this contract is ownerBefore (deployer), direct call represents owner-invocation
        // We capture revert via try/catch by calling the function through the contract type.
        try c.setOwner(newOwner) returns (bool success) {
            reverted = false;
            ret = success;
        } catch {
            reverted = true;
            ret = false;
        }

        address ownerAfter = c.owner();

        // General rule: If the caller (this contract) was the ownerBefore then the call must not revert,
        // must return true, and ownerAfter must equal newOwner. Otherwise, if caller was not ownerBefore it must revert and owner stays the same.
        // Here msg.sender for the call is address(this). So check ownership relation with ownerBefore.
        bool callerWasOwner = (address(this) == ownerBefore);

        assert(
            // if callerWasOwner then call succeeded and owner updated
            (callerWasOwner && !reverted && ret == true && ownerAfter == newOwner)
            // else the call reverted and owner unchanged
            || (!callerWasOwner && reverted && ownerAfter == ownerBefore)
        );
    }

    receive() external payable {}
}

