contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entrypoint for the property-based test
    // params: callerIsOwner chooses whether this contract will attempt the call as owner (true) or not (false)
    // newOwner is the address to set; it can be any address
    function run(bool callerIsOwner, address newOwner) public payable {
        require(true);

        // read initial owner
        address ownerBefore = c.owner();

        // We need to call setOwner from msg.sender == owner to succeed.
        // The InvMutTest contract deployed c, so initial owner is the deployer of c (constructor of C set owner to msg.sender at its deployment).
        // In the single-transaction model described, msg.sender for calls from this contract is this contract itself.
        // To simulate a non-owner call, we just call setOwner directly (this contract may or may not be the owner).
        // To simulate an owner call, we first, if needed, ensure this contract is the owner by calling setOwner from this contract only if it is already owner.
        // But we cannot impersonate other addresses. So the only way this contract can be owner is if ownerBefore == address(this).
        // We model two cases via callerIsOwner parameter but the actual call will be made by this contract in all cases.

        bool callReverted;
        bool ret;

        // Attempt the call and capture whether it reverts
        try c.setOwner(newOwner) returns (bool success) {
            callReverted = false;
            ret = success;
        } catch {
            callReverted = true;
            ret = false;
        }

        address ownerAfter = c.owner();

        // General rule asserted:
        // - If this contract was the ownerBefore (ownerBefore == address(this)), then the call must not revert and must return true, and ownerAfter == newOwner.
        // - If this contract was not the ownerBefore, then the call must revert and ownerAfter == ownerBefore.
        assert(
            (ownerBefore == address(this) && callReverted == false && ret == true && ownerAfter == newOwner)
            ||
            (ownerBefore != address(this) && callReverted == true && ownerAfter == ownerBefore)
        );
    }

    receive() external payable {}
}

