contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function taking an address caller and a candidate new owner
    // We simulate two calls: one from the correct owner (this contract) and one from an attacker
    // Because the checker runs this in one transaction and msg.sender for calls to c is this contract,
    // we cannot change msg.sender. To test both behaviors, we use the public getter and a try/catch
    // when calling setOwner: one call is the legitimate setOwner(from owner) which should succeed,
    // and another attempt to set owner back to some address by calling setOwner again will succeed
    // only if msg.sender equals current owner. Since msg.sender is this contract, the rule tested is:
    // - If a call to setOwner(from this contract) succeeds then owner becomes the provided address and returns true.
    // - If a call to setOwner(from this contract) reverts then owner remains unchanged.
    function run(address attackerCandidate, address newOwner) public payable {
        require(true);

        // Read initial owner
        address before = c.owner();

        // First attempt: try to set owner to newOwner. Since msg.sender for calls to c is this contract,
        // this attempt should succeed iff this contract is the current owner. Capture revert flag and return value.
        bool revertedFirst;
        bool retFirst = false;
        try c.setOwner(newOwner) returns (bool r) {
            revertedFirst = false;
            retFirst = r;
        } catch {
            revertedFirst = true;
        }

        // Read owner after first attempt
        address afterFirst = c.owner();

        // Now attempt a second call to setOwner to attackerCandidate, capturing revert.
        // This checks that only the current owner (which may have changed) can set owner again.
        bool revertedSecond;
        bool retSecond = false;
        try c.setOwner(attackerCandidate) returns (bool r2) {
            revertedSecond = false;
            retSecond = r2;
        } catch {
            revertedSecond = true;
        }

        address afterSecond = c.owner();

        // General invariant asserted:
        // 1) If the first call did not revert, it must have returned true and owner became newOwner.
        // 2) If the first call reverted, owner must remain as before.
        // 3) For the second call: it succeeds (does not revert) iff msg.sender (this contract) equals owner at that time;
        //    if it succeeds it must return true and owner becomes attackerCandidate; if it reverts, owner unchanged.
        // We encode these as a single boolean assertion combining the above.
        assert(
            (
                (!revertedFirst && retFirst && afterFirst == newOwner)
                || (revertedFirst && afterFirst == before)
            )
            &&
            (
                (!revertedSecond && retSecond && afterSecond == attackerCandidate && afterFirst == address(this))
                || (revertedSecond && afterSecond == afterFirst)
            )
        );
    }

    // Allow receiving ETH just in case
    receive() external payable {}
}

